import React from "react";
import Myinfo from "./myInfoProfileComponent";
import Posts from "./postsComponenet";
import Otherinfo from "./otherInfoProfileComponent";

class Profile extends React.Component {
    constructor(props){
        super(props);
        this.state = {
            loading:true,
            user: null,
            posts: null,
            base_URL: ""
        };
    }

    componentDidMount() {
        let token = localStorage.getItem("token");

        if (!token) {
            window.location.href = "/login";
            return;
        }

        fetch("http://localhost:8000/api/profile", {
            headers: {
                "Accept": "application/json",
                "Authorization": "Bearer " + token
            }
        })
        .then(res => res.json())
        .then(json => {
            console.log(json.user);
            this.setState({
                user: json.user,
                posts: json.posts,
                base_URL: json.base_URL,
                loading:false
            });
            console.log('aa');
        })
        .catch(err => console.log("ERR:", err));
    }
